.event-sim-container {
    padding: 28px;
    background: linear-gradient(135deg, #0a1929 0%, #122e4a 50%, #0d3447 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8eef5;
}

.event-sim-container .event-sim-header {
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 26px 32px;
    margin-bottom: 24px;
    background: linear-gradient(135deg, rgba(212,167,71,0.10), rgba(77,212,172,0.06));
    border: 1px solid rgba(212,167,71,0.18);
    border-left: 4px solid #d4a747;
    border-radius: 14px;
}
.event-sim-container .event-sim-brand {
    display: flex;
    align-items: center;
    gap: 14px;
}
.event-sim-container .event-sim-brand-mark {
    font-size: 1.6rem;
    color: #d4a747;
    letter-spacing: 0.05em;
}
.event-sim-container .event-sim-header h1 {
    margin: 0;
    font-size: 1.5rem;
    letter-spacing: 0.01em;
    color: #f5e9c8;
    font-weight: 600;
}
.event-sim-container .event-sim-period-strip {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 8px;
    font-size: 0.78rem;
    color: #9bb0c8;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}
.event-sim-container .event-sim-period-strip .event-sim-period-label {
    font-weight: 700;
    color: #d4a747;
}
.event-sim-container .event-sim-period-num {
    font-weight: 700;
    color: #f5e9c8;
    font-size: 1.1rem;
    letter-spacing: 0;
}
.event-sim-container .event-sim-period-title {
    text-transform: none;
    letter-spacing: 0;
    color: #cdd9e8;
    font-style: italic;
    font-size: 0.95rem;
    margin-left: 4px;
}

.event-sim-container .event-sim-briefing {
    padding: 22px 28px;
    margin-bottom: 26px;
    background: rgba(13,28,52,0.7);
    border: 1px solid rgba(155,176,200,0.18);
    border-left: 3px solid #4dd4ac;
    border-radius: 12px;
    font-size: 0.96rem;
    line-height: 1.65;
}
.event-sim-container .event-sim-briefing-from {
    font-size: 0.72rem;
    color: #4dd4ac;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
    font-weight: 700;
}
.event-sim-container .event-sim-briefing-text {
    color: #cdd9e8;
}

.event-sim-container .event-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.event-sim-container .event-sim-kpi-card {
    background: rgba(13,28,52,0.75);
    border: 1px solid rgba(155,176,200,0.15);
    border-radius: 10px;
    padding: 18px 18px 16px;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, border-color 0.2s ease;
}
.event-sim-container .event-sim-kpi-card:hover {
    transform: translateY(-2px);
    border-color: rgba(212,167,71,0.45);
}
.event-sim-container .event-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #d4a747, #4dd4ac);
}
.event-sim-container .event-sim-kpi-label {
    font-size: 0.7rem;
    color: #9bb0c8;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.event-sim-container .event-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #f5e9c8;
    line-height: 1.1;
}

.event-sim-container .event-sim-console {
    background: rgba(10,25,45,0.82);
    border: 1px solid rgba(155,176,200,0.15);
    border-radius: 14px;
    padding: 28px 30px;
    margin-bottom: 26px;
}
.event-sim-container .event-sim-console h3 {
    font-size: 0.95rem;
    color: #d4a747;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin: 0 0 22px 0;
    font-weight: 700;
    padding-bottom: 12px;
    border-bottom: 1px solid rgba(212,167,71,0.25);
}
.event-sim-container .event-sim-decision {
    margin-bottom: 18px;
    display: grid;
    grid-template-columns: 1fr;
    gap: 6px;
}
.event-sim-container .event-sim-decision label {
    font-size: 0.85rem;
    color: #cdd9e8;
    font-weight: 500;
    margin-bottom: 4px;
}

.event-sim-container .event-sim-console select,
.event-sim-container .event-sim-console input[type="number"],
.event-sim-container .event-sim-console input[type="text"] {
    background: #0a1929;
    border: 1px solid rgba(155,176,200,0.28);
    color: #e8eef5;
    border-radius: 6px;
    padding: 10px 32px 10px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
    appearance: none;
    -webkit-appearance: none;
    background-image: linear-gradient(45deg, transparent 50%, #d4a747 50%), linear-gradient(135deg, #d4a747 50%, transparent 50%);
    background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
    background-size: 5px 5px, 5px 5px;
    background-repeat: no-repeat;
}
.event-sim-container .event-sim-console input[type="number"],
.event-sim-container .event-sim-console input[type="text"] {
    background-image: none;
    padding-right: 12px;
}
.event-sim-container .event-sim-console select option {
    background: #122e4a;
    color: #e8eef5;
}
.event-sim-container .event-sim-console select:focus,
.event-sim-container .event-sim-console input:focus {
    outline: none;
    border-color: #d4a747;
    box-shadow: 0 0 0 2px rgba(212,167,71,0.22);
}

.event-sim-container .event-sim-actions {
    margin-top: 8px;
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    align-items: center;
}
.event-sim-container .event-sim-console .btn {
    border-radius: 8px;
    font-weight: 600;
    letter-spacing: 0.04em;
    padding: 12px 24px;
    transition: all 0.2s ease;
}
.event-sim-container .event-sim-console .btn-primary {
    background: linear-gradient(135deg, #d4a747, #c89530);
    border: none;
    color: #0a1929;
}
.event-sim-container .event-sim-console .btn-primary:hover {
    background: linear-gradient(135deg, #e0b75a, #d4a747);
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(212,167,71,0.30);
    color: #0a1929;
}
.event-sim-container .event-sim-console .btn-outline-secondary {
    background: transparent;
    border: 1px solid rgba(155,176,200,0.32);
    color: #9bb0c8;
}
.event-sim-container .event-sim-console .btn-outline-secondary:hover {
    border-color: #cdd9e8;
    color: #e8eef5;
    background: rgba(155,176,200,0.06);
}

.event-sim-container .event-sim-history {
    background: rgba(10,25,45,0.7);
    border: 1px solid rgba(155,176,200,0.15);
    border-radius: 14px;
    padding: 24px 26px;
    margin-bottom: 26px;
    overflow-x: auto;
}
.event-sim-container .event-sim-history h3 {
    font-size: 0.95rem;
    color: #4dd4ac;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin: 0 0 18px 0;
    font-weight: 700;
}
.event-sim-container .event-sim-history table {
    color: #cdd9e8;
    font-size: 0.85rem;
    margin-bottom: 0;
    width: 100%;
}
.event-sim-container .event-sim-history table th {
    color: #d4a747;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.08em;
    border-bottom: 1px solid rgba(212,167,71,0.30);
    padding: 10px 8px;
    background: transparent;
}
.event-sim-container .event-sim-history table td {
    border-top: 1px solid rgba(155,176,200,0.10);
    padding: 10px 8px;
    color: #e8eef5;
}
.event-sim-container .event-sim-history table tr:hover td {
    background: rgba(212,167,71,0.04);
}

.event-sim-container .event-sim-chart {
    background: rgba(10,25,45,0.7);
    border: 1px solid rgba(155,176,200,0.15);
    border-radius: 14px;
    padding: 24px;
    height: 380px;
}

@media (max-width: 768px) {
    .event-sim-container { padding: 16px; }
    .event-sim-container .event-sim-header { padding: 18px 20px; }
    .event-sim-container .event-sim-header h1 { font-size: 1.2rem; }
    .event-sim-container .event-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .event-sim-container .event-sim-kpi-value { font-size: 1.35rem; }
    .event-sim-container .event-sim-console { padding: 20px; }
    .event-sim-container .event-sim-chart { height: 280px; }
}

