(function() {
    'use strict';

    class HelioConferenceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'HelioConnect 2026 — The Corporate Conference';
            this.version = '1.1.0';
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 740000,
                    spent: 0,
                    attendees: 0,
                    regRevenue: 0,
                    sponsorRevenue: 0,
                    attendeeNPS: 0,
                    sponsorNPS: 0,
                    contractRobust: false,
                    weatherHoldBought: false,
                    allergenChecklist: false,
                    sponsorContractsSpecific: false,
                    venueChoice: '',
                    avChoice: '',
                    score: 0,
                    scoreHistory: [],
                    spendHistory: [],
                    npsHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    venue: 'convention',
                    av: 'hybrid',
                    speakerContract: 'robust',
                    weatherHold: 'yes',
                    regTier: '3tier',
                    sponsorContract: 'specific',
                    allergen: 'checklist',
                    promo: 'partner',
                    regStations: '4',
                    avTest: 'full',
                    lunchStations: '9',
                    sponsorComplaint: 'hold-recover',
                    keynoteCrisis: 'bureau-backup',
                    avCrisis: 'cue-fill',
                    dietaryCrisis: 'pull-document',
                    weatherCrisis: 'move-indoors'
                };
            }
            var self = this;
            self._updateBriefing(state);
        }

        validateDecisions(decisions) {
            this._readInputs(decisions);
            return true;
        }

        _readInputs(decisions) {
            var map = {
                venueInput: 'venue', avInput: 'av', speakerInput: 'speakerContract', weatherInput: 'weatherHold',
                regTierInput: 'regTier', sponsorInput: 'sponsorContract', allergenInput: 'allergen', promoInput: 'promo',
                regStationsInput: 'regStations', avTestInput: 'avTest', lunchInput: 'lunchStations', sponsorComplaintInput: 'sponsorComplaint',
                keynoteCrisisInput: 'keynoteCrisis', avCrisisInput: 'avCrisis', dietaryCrisisInput: 'dietaryCrisis', weatherCrisisInput: 'weatherCrisis'
            };
            Object.keys(map).forEach(function(id) {
                var el = document.getElementById(id);
                if (el && el.value) decisions[map[id]] = el.value;
            });
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var roundScore = 0;

            if (period === 1) {
                var venueCosts = { 'w-austin': 460000, 'fairmont': 380000, 'convention': 255000 };
                var avCosts = { 'encore': 215000, 'hybrid': 128000, 'lone-star': 158000 };
                var venueCost = venueCosts[d.venue] || 380000;
                var avCost = avCosts[d.av] || 128000;
                var speakerCost = d.speakerContract === 'robust' ? 78000 : 75000;
                var weatherCost = d.weatherHold === 'yes' ? 12000 : 0;
                var fixedOps = 95000;

                ds.spent += venueCost + avCost + speakerCost + weatherCost + fixedOps;
                ds.venueChoice = d.venue;
                ds.avChoice = d.av;
                ds.contractRobust = (d.speakerContract === 'robust');
                ds.weatherHoldBought = (d.weatherHold === 'yes');

                if (d.venue === 'convention') roundScore += 18;
                else if (d.venue === 'fairmont') roundScore += 12;
                else roundScore += 4;

                if (d.av === 'hybrid') roundScore += 18;
                else if (d.av === 'encore') roundScore += 12;
                else roundScore += 4;

                roundScore += d.speakerContract === 'robust' ? 18 : 4;
                roundScore += d.weatherHold === 'yes' ? 16 : 4;
            }

            if (period === 2) {
                var avgPrice = 0, attendees = 0;
                if (d.regTier === '3tier') { avgPrice = 825; attendees = 600; }
                else if (d.regTier === '2tier') { avgPrice = 920; attendees = 540; }
                else { avgPrice = 350; attendees = 620; }

                var promoBoost = { 'partner': 50, 'linkedin': 75, 'customer': 25, 'early-bird': 90 };
                attendees += (promoBoost[d.promo] || 0);
                if (d.promo === 'early-bird') avgPrice = Math.round(avgPrice * 0.78);
                if (d.promo === 'linkedin') ds.spent += 18000;

                attendees = Math.min(attendees, 650);
                ds.attendees = attendees;
                ds.regRevenue = Math.round(attendees * avgPrice);

                if (d.sponsorContract === 'specific') {
                    ds.sponsorRevenue = 185000;
                    ds.sponsorContractsSpecific = true;
                    roundScore += 20;
                } else {
                    ds.sponsorRevenue = 162000;
                    ds.sponsorContractsSpecific = false;
                    roundScore += 6;
                }

                if (d.allergen === 'checklist') { ds.allergenChecklist = true; roundScore += 18; }
                else if (d.allergen === 'email') { ds.allergenChecklist = false; roundScore += 6; }
                else { ds.allergenChecklist = false; roundScore += 0; }

                if (d.regTier === '3tier') roundScore += 18;
                else if (d.regTier === '2tier') roundScore += 12;
                else roundScore += 8;

                if (d.promo === 'partner') roundScore += 12;
                else if (d.promo === 'linkedin') roundScore += 14;
                else if (d.promo === 'customer') roundScore += 8;
                else roundScore += 4;
            }

            if (period === 3) {
                var npsAtt = 7.2, npsSpons = 7.0;

                if (d.regStations === '6') npsAtt += 0.6;
                else if (d.regStations === '4') npsAtt += 0.3;
                else npsAtt -= 0.5;

                if (d.avTest === 'full') npsAtt += 0.4;
                else if (d.avTest === 'partial') npsAtt -= 0.1;
                else npsAtt -= 0.6;

                if (d.lunchStations === '9') npsAtt += 0.4;
                else if (d.lunchStations === '7-stagger') npsAtt += 0.1;
                else npsAtt -= 0.3;

                if (d.sponsorComplaint === 'hold-recover') npsSpons += 0.6;
                else if (d.sponsorComplaint === 'cave') npsSpons -= 0.3;
                else npsSpons -= 0.7;

                if (ds.avChoice === 'lone-star') npsAtt -= 0.3;
                if (ds.sponsorContractsSpecific) npsSpons += 0.4; else npsSpons -= 0.4;

                ds.attendeeNPS = Math.max(0, Math.min(10, npsAtt));
                ds.sponsorNPS = Math.max(0, Math.min(10, npsSpons));

                if (d.regStations === '6') roundScore += 14;
                else if (d.regStations === '4') roundScore += 10;
                else roundScore += 4;

                if (d.avTest === 'full') roundScore += 14;
                else if (d.avTest === 'partial') roundScore += 6;
                else roundScore += 0;

                if (d.lunchStations === '9') roundScore += 12;
                else if (d.lunchStations === '7-stagger') roundScore += 8;
                else roundScore += 4;

                if (d.sponsorComplaint === 'hold-recover') roundScore += 16;
                else if (d.sponsorComplaint === 'cave') roundScore += 6;
                else roundScore += 0;
            }

            if (period === 4) {
                var crisisScore = 0;
                var attDelta = 0, sponsDelta = 0;

                if (d.keynoteCrisis === 'bureau-backup') {
                    if (ds.contractRobust) { crisisScore += 25; attDelta += 0.2; }
                    else { crisisScore += 8; attDelta -= 0.6; }
                } else if (d.keynoteCrisis === 'exec-fireside') {
                    crisisScore += 18; attDelta -= 0.1;
                } else {
                    crisisScore += 0; attDelta -= 1.5; sponsDelta -= 1.0;
                }

                if (d.avCrisis === 'cue-fill') { crisisScore += 22; sponsDelta += 0.1; }
                else if (d.avCrisis === 'break') { crisisScore += 10; attDelta -= 0.2; }
                else { crisisScore += 0; attDelta -= 0.6; }

                if (ds.avChoice === 'lone-star' && d.avCrisis !== 'cue-fill') {
                    sponsDelta -= 0.2;
                }

                if (d.dietaryCrisis === 'pull-document') {
                    crisisScore += 25;
                    if (ds.allergenChecklist) crisisScore += 5;
                } else if (d.dietaryCrisis === 'verbal-save') {
                    crisisScore += 8; attDelta -= 0.2;
                } else {
                    crisisScore += 0; attDelta -= 0.7;
                }

                if (d.weatherCrisis === 'move-indoors') {
                    crisisScore += 22;
                    if (!ds.weatherHoldBought) ds.spent += 18000; else crisisScore += 5;
                    sponsDelta += 0.2;
                } else if (d.weatherCrisis === 'hybrid') {
                    crisisScore += 12;
                    if (!ds.weatherHoldBought) ds.spent += 9000;
                } else {
                    crisisScore += 0; attDelta -= 0.8; sponsDelta -= 0.7;
                }

                ds.attendeeNPS = Math.max(0, Math.min(10, ds.attendeeNPS + attDelta));
                ds.sponsorNPS = Math.max(0, Math.min(10, ds.sponsorNPS + sponsDelta));

                roundScore = Math.min(crisisScore, 95);
            }

            ds.score += roundScore;
            ds.scoreHistory.push(ds.score);
            ds.spendHistory.push(Math.round(ds.spent / 1000));
            ds.npsHistory.push(Math.round(((ds.attendeeNPS + ds.sponsorNPS) / 2) * 10) / 10);

            var cpa = ds.attendees > 0 ? Math.round(ds.spent / ds.attendees) : 0;

            var self = this;
            /* v1.1.0: removed racy setTimeout N+2 desync; panel refreshes on the real period:submitted / period:undone events wired in setupUI. */

            return {
                period: period,
                roundScore: roundScore,
                cumulativeScore: ds.score,
                spent: ds.spent,
                attendees: ds.attendees,
                cpa: cpa,
                sponsorRevenue: ds.sponsorRevenue,
                attendeeNPS: Math.round(ds.attendeeNPS * 10) / 10,
                sponsorNPS: Math.round(ds.sponsorNPS * 10) / 10
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.spent', function(v) {
                var remaining = 740000 - (v || 0);
                return '$' + Math.round(remaining / 1000).toLocaleString() + 'K';
            });
            uiManager.bind('cpaDisplay', 'domainState.spent', function(v) {
                var s = window.mySimulation && window.mySimulation.state ? window.mySimulation.state : null;
                var att = s && s.domainState ? s.domainState.attendees : 0;
                if (!att) return '—';
                return '$' + Math.round((v || 0) / att).toLocaleString();
            });
            uiManager.bind('attendeesDisplay', 'domainState.attendees');
            uiManager.bind('sponsorRevDisplay', 'domainState.sponsorRevenue', function(v) {
                return '$' + Math.round((v || 0) / 1000) + 'K';
            });
            uiManager.bind('attNpsDisplay', 'domainState.attendeeNPS', function(v) {
                return v > 0 ? (Math.round(v * 10) / 10).toFixed(1) : '—';
            });
            uiManager.bind('sponsNpsDisplay', 'domainState.sponsorNPS', function(v) {
                return v > 0 ? (Math.round(v * 10) / 10).toFixed(1) : '—';
            });


            if (!this._wired) {
                var _self = this;
                var _refresh = function() { try { _self._updateBriefing(window.mySimulation.state); } catch (e) {} };
                var _sim = window.mySimulation;
                if (_sim && _sim.eventBus && typeof _sim.eventBus.on === 'function') {
                    _sim.eventBus.on('period:submitted', _refresh);
                    _sim.eventBus.on('period:undone', _refresh);
                }
                document.addEventListener('express:langchanged', _refresh);
                this._wired = true;
            }
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Cumulative Score',
                                data: [],
                                borderColor: '#d4a747',
                                backgroundColor: 'rgba(212,167,71,0.18)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Average NPS',
                                data: [],
                                borderColor: '#4dd4ac',
                                backgroundColor: 'rgba(77,212,172,0.10)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                yAxisID: 'y2'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Performance Across Rounds', color: '#e8eef5' },
                            legend: { labels: { color: '#e8eef5' } }
                        },
                        scales: {
                            x: { ticks: { color: '#9bb0c8' }, grid: { color: 'rgba(155,176,200,0.10)' } },
                            y: { beginAtZero: true, max: 320, ticks: { color: '#d4a747' }, grid: { color: 'rgba(155,176,200,0.10)' }, title: { display: true, text: 'Score', color: '#d4a747' } },
                            y2: { beginAtZero: true, max: 10, position: 'right', ticks: { color: '#4dd4ac' }, grid: { drawOnChartArea: false }, title: { display: true, text: 'NPS', color: '#4dd4ac' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.scoreHistory },
                        { data: state.domainState.npsHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var totalScore = (last.results && last.results.cumulativeScore) || 0;
            var cpa = (last.results && last.results.cpa) || 0;
            var attNps = (last.results && last.results.attendeeNPS) || 0;
            var sponsNps = (last.results && last.results.sponsorNPS) || 0;

            var performance = 'Beginner';
            if (totalScore >= 230) performance = 'Excellent';
            else if (totalScore >= 175) performance = 'Good';
            else if (totalScore >= 125) performance = 'Developing';

            var insights = [];
            if (cpa > 1100) insights.push('Cost-per-attendee finished above the $900–$1,100 SaaS-conference benchmark. Defend the spend or trim the venue line for HelioConnect 2027.');
            else if (cpa > 0) insights.push('Cost-per-attendee landed inside or below the industry benchmark — defensible to the CFO.');
            if (sponsNps >= 7.5) insights.push('Sponsor NPS clears the 7.5 renewal threshold — expect the 62–78% FY27 renewal band.');
            else if (sponsNps > 0) insights.push('Sponsor NPS sits below 7.5 — the FY27 renewal rate falls into the 30–45% band.');
            if (attNps >= 8.0) insights.push('Attendee NPS hit the 8.0 conference target — pipeline conversion will follow.');
            else if (attNps > 0) insights.push('Attendee NPS came in under 8.0 — review registration flow, A/V, and F&B throughput.');
            if (totalScore < 150) insights.push('Several Round 1 contracting gaps cascaded into Day 2. Re-run focusing on force-majeure language, A/V redundancy, and the weather hold.');

            return {
                totalScore: totalScore,
                cpa: cpa,
                attendeeNPS: attNps,
                sponsorNPS: sponsNps,
                performance: performance,
                insights: insights
            };
        }

